sys_transform_script.script:
(function runTransformScript(source, map, log, target) {

    // Check whether the required source field exists
    if (!source.isValidField('customer_code_sap')) {
        ignore = true;
        log.info('Skipping row: customer_code_sap field is missing');
        return;
    }

    // Allow only updates, not inserts
    if (action == 'insert') {
        ignore = true;
    }

})(source, map, log, target);
